"定义一个求平方根的函数sqrt(n):
    low = 0
    high = n

    while low <= high:
        mid = (low + high) // 2
        if mid * mid == n:
            return mid
        elif mid * mid < n:
            low = mid + 1
        else:
            high = mid - 1

    return low - 1"

'import random
def random_array(n):
    arr = []
    for i in range(n):
        arr.append(random.randint(0, 100))
    return arr'
中文翻译：'导入随机模块
def random_array(n):
    arr = []
    for i in range(n):
        arr.append(random.randint(0, 100))
    return arr'

'def count_unique_chars(string):
  char_dict = {}
  for char in string:
    if char in char_dict:
      char_dict[char] += 1
    else:
      char_dict[char] = 1
  return len(char_dict)

print(count_unique_chars("Butterflies"))
# Output: 9'

"计算唯一字符数的函数：def count_unique_chars(string)： char_dict = {} for char in string: if char in char_dict: char_dict[char] += 1 else: char_dict[char] = 1 return len(char_dict) 打印输出唯一字符数：print(count_unique_chars("Butterflies")) # 输出：9"
